from pyspark.sql import functions as F


def solve(orders):
    facts = F.array(
        F.struct(F.lit("status").alias("field"), F.col("status").alias("value")),
        F.struct(F.lit("channel").alias("field"), F.col("status").alias("value")),
    )
    return orders.select("order_id", F.explode(facts).alias("fact")).select("order_id", "fact")
